const mimeType = $json.mimeType || '';
const name = $json.name || '';
let allowed = true;
let doc_type = 'text';
let export_mime_type = null;

if (mimeType === 'application/vnd.google-apps.document') {
  doc_type = 'doc';
  export_mime_type = 'text/plain';
} else if (mimeType === 'application/vnd.google-apps.spreadsheet') {
  allowed = false;
} else if (mimeType === 'application/vnd.google-apps.presentation') {
  allowed = false;
} else if (mimeType === 'application/pdf') {
  doc_type = 'pdf';
  export_mime_type = null;
} else if (mimeType.includes('word')) {
  doc_type = 'word';
} else if (mimeType.includes('text/plain') || name.endsWith('.md')) {
  doc_type = 'text';
} else {
  allowed = false;
}

if (!allowed) return [];

return [{ json: { ...$json, doc_type, export_mime_type, allowed } }];

const name = $json.name || '';
const topic = name.includes(' - ') ? name.split(' - ')[0].trim() : name.split('.')[0];
const versionMatch = name.match(/v(\d+)/i);
const version = versionMatch ? parseInt(versionMatch[1], 10) : 1;

return [{
  json: {
    metadata: {
      source: 'google_drive',
      kb_collection: 'YTUMA_Knowledge_Base',
      drive_file_id: $json.id,
      drive_name: name,
      drive_mime_type: $json.mimeType,
      stored_mime_type: $json.export_mime_type || $json.mimeType,
      doc_type: $json.doc_type,
      topic,
      ingested_at: new Date().toISOString(),
      version,
      drive_web_view_link: $json.webViewLink,
      drive_modified_time: $json.modifiedTime,
      ingested_by_workflow: '05_YTUMA_Knowledge_Base'
    }
  },
  binary: $binary
}];
